245	// Drives the app through its screens, binding only to data-testid (AGENTS.md §2). Every test
246	// arranges its own data with these helpers and asserts through them or through data-testid
247	// directly. An action helper returns what the screen reported: an id when a row was created,
248	// true/false for whether the action went through or the screen refused it (its error element
249	// appeared). It throws when neither a result nor an error shows within the wait, so a screen that
250	// does nothing fails the test instead of passing as "refused".
251	import { expect, test, type Browser, type BrowserContext, type Locator, type Page } from '@playwright/test';
252	import { existsSync, readFileSync } from 'node:fs';
253	
254	const AUDIT_FILE = process.env.AUDIT_FILE ?? '../.run/audit.log';
255	const WAIT = 8000;
256	const LOAD_WAIT = 30000;      // a sign-in, a sheet load or a today change: the whole sheet is re-read
257	const ERROR_GRACE = 2000;     // how long an error left over from the action before may linger
258	const AUDIT_WAIT = 3000;      // how long an audit line may lag the screen
259	
260	const editing = new WeakMap<Page, string>();
261	
262	export function sheetId(): string {
263	  return 's' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
264	}
265	
266	/** The id a creating helper returned; throws when the screen refused (null) so the failure
267	 *  lands on the arranging line rather than on a later assertion. */
268	export function must(id: string | null): string {
269	  if (id === null) throw new Error('the screen refused this action (its error element appeared)');
270	  return id;
271	}
272	
273	function escapeRe(s: string): string {
274	  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
275	}
276	
277	/** The trimmed text of a locator, read without waiting: '' when it is not on the page. A poll
278	 *  must never use an auto-waiting read (textContent, getAttribute) on an element that may be
279	 *  re-rendered or removed while it polls; that read would block until the test's own timeout. */
280	async function shown(loc: Locator): Promise<string> {
281	  return ((await loc.allTextContents())[0] ?? '').trim();
282	}
283	
284	/** The ids carried by every element matching `loc`, read without waiting. */
285	async function ids(loc: Locator, prefix: string): Promise<string[]> {
286	  const out: string[] = [];
287	  for (const h of await loc.elementHandles()) out.push(idOf(await h.getAttribute('data-testid'), prefix));
288	  return out;
289	}
290	
291	/** The rows matching `loc` whose id is not in `before`, in screen order, each with its id and the
292	 *  text of the named cells; read without waiting, so a poll may call it. A creating helper finds
293	 *  its row this way: a page may be showing the sheet as it was when it was loaded, so the rows
294	 *  other users added can land on it at any moment, including between a submit and its result. */
295	async function freshRows(loc: Locator, prefix: string, before: string[], cells: string[]): Promise<Record<string, string>[]> {
296	  const out: Record<string, string>[] = [];
297	  try {
298	    for (const h of await loc.elementHandles()) {
299	      const testid = (await h.getAttribute('data-testid')) ?? '';
300	      if (!testid.startsWith(prefix) || before.includes(testid.slice(prefix.length))) continue;
301	      const x: Record<string, string> = { id: testid.slice(prefix.length) };
302	      for (const c of cells) x[c] = ((await (await h.$(`[data-testid="${c}"]`))?.textContent()) ?? '').trim();
303	      out.push(x);
304	    }
305	  } catch {
306	    return [];                            // a row was re-rendered mid-read: the poll looks again
307	  }
308	  return out;
309	}
310	
311	/** An amount as the screen shows it: two decimals, a dot, no grouping. */
312	function money(amount: string): string {
313	  const n = Number(amount.trim());
314	  return amount.trim() !== '' && Number.isFinite(n) ? n.toFixed(2) : amount;
315	}
316	
317	/** A name as a name cell shows it, without a trailing " (<grade>)" the screen may append. */
318	function plainName(shown: string): string {
319	  return shown.trim().replace(/\s\([^()]*\)$/, '');
320	}
321	
322	/** The id of a person row new since `before` whose name is `name` (case and outer spaces
323	 *  ignored), or null when none shows yet. */
324	async function addedPerson(page: Page, before: string[], name: string): Promise<string | null> {
325	  const want = name.trim().toLowerCase();
326	  const hit = (await freshRows(rows(page), 'person-row-', before, ['person-name'])).find((p) => plainName(p['person-name']).toLowerCase() === want);
327	  return hit ? hit.id : null;
328	}
329	
330	/** The id of a claim row under `scope` new since `before` showing the amount (and the date,
331	 *  when one was given) that was entered, or null when none shows yet; the first in screen order
332	 *  (newest first) when more than one does. */
333	async function addedClaim(scope: Locator, before: string[], f: ClaimFields): Promise<string | null> {
334	  const want = money(f.amount ?? '');
335	  const hit = (await freshRows(claimRows(scope), 'claim-row-', before, ['claim-amount', 'claim-date']))
