340	/** The id of the first claim row under `scope` new since `before`, or null when none shows yet. */
341	async function addedAnyClaim(scope: Locator, before: string[]): Promise<string | null> {
342	  const hit = (await freshRows(claimRows(scope), 'claim-row-', before, []))[0];
343	  return hit ? hit.id : null;
344	}
345	
346	function idOf(testid: string | null, prefix: string): string {
347	  if (!testid || !testid.startsWith(prefix)) throw new Error(`no ${prefix}* id on ${testid}`);
348	  return testid.slice(prefix.length);
349	}
350	
351	/** Poll until `done` holds (true) or `error` is visible (false); throw when neither happens.
352	 *  Each check returns as soon as it can. An error already visible at the first look after the
353	 *  click may be left over from the action before (the screen clears it when a new action is
354	 *  submitted, see README): it counts as this action's refusal once it has gone away and been
355	 *  shown again, once its text changes, or once ERROR_GRACE has passed with no result.
356	 *  `already` says `done` held BEFORE the action (watching a person already watched, saving a
357	 *  setting at its current value): then the result on screen proves nothing, and the action
358	 *  counts as taken only once ERROR_GRACE has passed with no refusal shown. */
359	async function until(page: Page, done: () => Promise<boolean>, error: Locator, what: string,
360	                     already = false): Promise<boolean> {
361	  const deadline = Date.now() + WAIT;
362	  let stale: string | null | undefined;   // text of an error visible at the first look; null if none
363	  let seenGone = false;
364	  const grace = Date.now() + ERROR_GRACE;
365	  while (Date.now() < deadline) {
366	    if (!already && await done()) return true;
367	    const visible = await error.isVisible().catch(() => false);
368	    if (stale === undefined) stale = visible ? await shown(error) : null;
369	    if (visible) {
370	      if (stale === null || seenGone || (await shown(error)) !== stale || Date.now() >= grace) return false;
371	    } else {
372	      seenGone = true;
373	    }
374	    // the state held before the action: an error still showing at the grace outranks it
375	    if (already && Date.now() >= grace && await done()) return true;
376	    await page.waitForTimeout(50);
377	  }
378	  if (await done()) return true;
379	  if (await error.isVisible().catch(() => false)) return false;
380	  throw new Error(`${what}: neither a result nor an error appeared within ${WAIT}ms`);
381	}
382	
383	async function sleep(ms: number): Promise<void> {
384	  await new Promise((r) => setTimeout(r, ms));
385	}
386	
387	/** A counter the screen shows after a bulk action: the number in the cell once it is visible. */
388	async function counter(page: Page, cell: Locator, error: Locator, what: string): Promise<number | null> {
