396	 *  the screen does not have is skipped. */
397	async function setField(scope: Locator | Page, testid: string, value: string | undefined): Promise<void> {
398	  const loc = scope.getByTestId(testid);
399	  if (value !== undefined) {
400	    await loc.fill(value);
401	  } else if ((await loc.count()) > 0) {
402	    await loc.fill('');
403	  }
404	}
405	
406	/** The result count a button shows once its action is done (how many were added, made, opened).
407	 *  `was` is what the cell showed before the click. The count is taken once it differs from `was`,
408	 *  or once the cell was seen cleared and shown again (README: a result is cleared when its button
409	 *  is pressed again). Two identical results in a row can look the same on screen for the whole
410	 *  wait: then, with no error showing and a value in the cell, that value is taken rather than
411	 *  failing a step the app did take. */
412	async function countAfter(page: Page, cell: Locator, error: Locator, what: string, was: string): Promise<string | null> {
413	  let cleared = false;
414	  const done = async () => {
415	    if ((await cell.count()) === 0) return false;
416	    const now = await shown(cell);
417	    if (now === '') { cleared = true; return false; }
418	    return now !== was || was === '' || cleared;
419	  };
420	  try {
421	    return (await until(page, done, error, what)) ? await shown(cell) : null;
422	  } catch (e) {
423	    if (await error.isVisible().catch(() => false)) return null;
424	    if ((await cell.count()) > 0 && (await shown(cell)) !== '') return shown(cell);
425	    throw e;
426	  }
427	}
