436	export async function userPage(browser: Browser, user: string, sheet: string): Promise<Page> {
437	  let owner = '';
438	  try { owner = test.info().testId; } catch { /* outside a test: nothing to tidy by */ }
439	  for (const [c, t] of opened) {
440	    if (t === owner) continue;
441	    opened.delete(c);
442	    await c.close().catch(() => { /* already gone */ });
443	  }
444	  const context = await browser.newContext();
445	  opened.set(context, owner);
446	  const page = await context.newPage();
447	  page.setDefaultTimeout(LOAD_WAIT);     // an element an action needs that never shows fails here, not at the test's limit
448	  await page.goto('/');
449	  await page.getByTestId('signin-name').fill(user);
450	  await page.getByTestId('signin-submit').click();
451	  await expect(page.getByTestId('current-user')).toHaveText(user, { timeout: LOAD_WAIT });
452	  await loadSheet(page, sheet);
453	  return page;
454	}
