462	/** Re-load the active sheet so the screen shows what the store holds now. Loading the same id
463	 *  again is not observable (the current id already reads that), so the screen first loads a
464	 *  throwaway id, which has no one on it, and waits for the person rows to go; then it loads the
465	 *  sheet again and waits for rows to show. Rows that were on screen before may rightly not come
466	 *  back (someone retired since, say), so the wait is for any row, and for every row that is back
467	 *  to carry at least the claims it had; if none shows within the wait the screen is taken as it
468	 *  is and the test's own checks decide. The show-retired box and the as-of date, which belong to
469	 *  the screen, are put back if the loads reset them. */
470	export async function refresh(page: Page): Promise<void> {
471	  const sheet = (await page.getByTestId('sheet-current-id').textContent() ?? '').trim();
472	  const before = new Map<string, number>();
473	  for (const id of await ids(rows(page), 'person-row-')) before.set(id, await claimRows(row(page, id)).count());
474	  const retired = page.getByTestId('show-retired');
475	  const showRetiredWas = (await retired.count()) > 0 ? await retired.isChecked() : null;
476	  const asofWas = await shown(page.getByTestId('sheet-asof'));
477	  const previewWas = await shown(page.getByTestId('sheet-preview'));
478	  await loadSheet(page, sheet + '-reload');
479	  await expect.poll(() => rows(page).count(), { message: 'the throwaway sheet, which has no one on it, is on screen', timeout: LOAD_WAIT }).toBe(0);
480	  await loadSheet(page, sheet);
481	  if (showRetiredWas !== null && (await retired.isChecked()) !== showRetiredWas) await retired.setChecked(showRetiredWas);
482	  if (asofWas !== '' && (await shown(page.getByTestId('sheet-asof'))) !== asofWas) await setAsOf(page, asofWas);
483	  if (previewWas !== '' && (await shown(page.getByTestId('sheet-preview'))) !== previewWas) await setPreview(page, previewWas);
484	  if (before.size === 0) return;
485	  const back = async () => {
486	    if ((await rows(page).count()) === 0) return false;
487	    for (const [id, n] of before) {
488	      const r = row(page, id);
489	      if ((await r.count()) > 0 && (await claimRows(r).count()) < n) return false;
490	    }
491	    return true;
492	  };
493	  const deadline = Date.now() + LOAD_WAIT;
494	  while (Date.now() < deadline && !(await back())) await page.waitForTimeout(50);
495	}
