595	export async function editSave(page: Page, f: PersonFields, shows?: Shows): Promise<boolean> {
596	  const id = editing.get(page);
597	  if (!id) throw new Error('editSave without editOpen');
598	  const want = typeof shows === 'string' ? { grade: shows } : (shows ?? {});
599	  const grade = want.grade ?? f.grade;                       // the grade the row shows once saved
600	  const terms = want.terms ?? f.terms;                       // the terms in force the row shows
601	  const r = row(page, id);
602	  const shows_ = async () => {
603	    if (f.name !== undefined && plainName(await shown(r.getByTestId('person-name'))) !== f.name.trim()) return false;
