1052	/** Submit the open claim editor with `f` and judge the outcome. When the typed values are what the
1053	 *  row already shows, the save cannot be seen on the row: the step then counts as saved only once
1054	 *  no error has shown for a while (the `already` rule of until()). */
1055	async function saveClaimEditor(page: Page, c: Locator, r: Locator, f: ClaimFields, what: string): Promise<boolean> {
1056	  await fillClaimForm(r, f);
1057	  const error = c.getByTestId('claim-error').or(r.getByTestId('claim-form-error'));
1058	  const was = await editedCells(c, f);
1059	  const already = await editedShows(c, f, was);
1060	  await r.getByTestId('claim-form-submit').click();
1061	  return until(page, async () => editedShows(c, f, was), error, what, already);
1062	}
