1071	/** The cells an edit will be judged by, as they are before the save. */
1072	async function editedCells(c: Locator, f: ClaimFields): Promise<Record<string, string>> {
1073	  const out: Record<string, string> = {};
1074	  for (const k of Object.keys(f)) out[k] = await shown(c.getByTestId(`claim-${k}`));
1075	  return out;
1076	}
