1078	/** Whether the row shows the edit: an amount, date, note or corrects cell equal to what was
1079	 *  typed; a ref or tags cell, which the app normalises, is taken as saved once the form's error
1080	 *  is not showing and the cell is no longer what it was (or the typed value, normalised, is a
1081	 *  value it could not have had before). */
1082	async function editedShows(c: Locator, f: ClaimFields, was: Record<string, string>): Promise<boolean> {
1083	  for (const [k, v] of Object.entries(f)) {
1084	    const cell = await shown(c.getByTestId(`claim-${k}`));
1085	    if (k === 'ref' || k === 'tags') {
1086	      const norm = k === 'ref' ? v.trim() : v.split(',').map((t) => t.trim().toLowerCase()).filter((t) => t)
1087	        .filter((t, i, a) => a.indexOf(t) === i).sort().join(', ');
1088	      if (cell !== norm) return false;
1089	    } else if (cell !== v) return false;
1090	  }
1091	  return true;
1092	}
